  "appearance_facts": [
    {"location": "Upper-left to mid-left sector", "fact": "The pale yellow wedge is the widest slice on the page, spanning roughly 162 degrees from the top vertical edge to the mid-left boundary."},
    {"location": "Right and upper-right sector", "fact": "The orange wedge is the second-largest visible area, occupying the entire right side from the top vertical edge to the lower-right boundary."},
    {"location": "Lower-left sector", "fact": "The dark red wedge is the third-largest visible area, situated between the pale yellow and orange-tan wedges on the left side."},
    {"location": "Bottom sector", "fact": "The orange-tan wedge is the smallest visible area, located at the bottom of the circle."}
  ],
  "printed_facts": [
    {"location": "Top-left header", "fact": "The title reads 'Global Energy Consumption by Source'."},
    {"location": "Center of pale yellow wedge", "fact": "The label reads 'Nuclear (45%)'."},
    {"location": "Center of orange wedge", "fact": "The label reads 'Hydroelectric (10%)'."},
    {"location": "Center of dark red wedge", "fact": "The label reads 'Fossil Fuels (30%)'."},
    {"location": "Center of orange-tan wedge", "fact": "The label reads 'Renewables (15%)'."}
  ],
  "public_definitions": [
    "The routing criterion is defined as the 'Largest global energy consumption category'."
  ],
  "uncertain": [
    "There is a visual discrepancy between the apparent size of the wedges and their printed percentage labels; the pale yellow wedge (labeled 45%) is the largest area, while the orange wedge (labeled 10%) is the second largest area."
  ]
}
